// ─────────────────────────── runtime tests ───────────────────────────────

test('focus records which field has the caret', () => {
  eq(reduce(EMPTY, { type: 'focus', field: 'email' }).focused, 'email');
});

test('change writes one value and leaves the rest alone', () => {
  const one = reduce(EMPTY, { type: 'change', field: 'email', value: 'a@b.c' });
  const two = reduce(one, { type: 'change', field: 'name', value: 'Ada' });
  eq(two.values, { email: 'a@b.c', name: 'Ada' });
});

test('blur clears focus and marks the field touched exactly once', () => {
  const focused = reduce(EMPTY, { type: 'focus', field: 'email' });
  const once = reduce(focused, { type: 'blur', field: 'email' });
  const twice = reduce(once, { type: 'blur', field: 'email' });
  eq(twice.focused, null);
  eq(twice.touched, ['email']);
});

test('submit stamps the time and drops focus', () => {
  const done = reduce(EMPTY, { type: 'submit', at: 1700000000 });
  eq(done.submittedAt, 1700000000);
  eq(done.focused, null);
});

test('reduce never mutates the state it was handed', () => {
  const before = reduce(EMPTY, { type: 'change', field: 'a', value: '1' });
  reduce(before, { type: 'change', field: 'b', value: '2' });
  eq(before.values, { a: '1' });
  ok(EMPTY.touched.length === 0);
});

test('an event that slips past the compiler blows up loudly', () => {
  throws(
    () => reduce(EMPTY, { type: 'reset' } as unknown as FormEvent),
    'unhandled variant'
  );
});

// ──────────────────────────── type tests ─────────────────────────────────

type _t1 = Expect<
  Equal<FormEvent['type'], 'focus' | 'change' | 'blur' | 'submit'>
>;
type _t2 = Expect<
  Equal<
    Extract<FormEvent, { type: 'change' }>,
    { type: 'change'; field: string; value: string }
  >
>;
type _t3 = Expect<Equal<Parameters<typeof assertNever>[0], never>>;
type _t4 = Expect<Equal<ReturnType<typeof reduce>, FormState>>;

function _typeTests() {
  const queue: FormEvent[] = [
    { type: 'change', field: 'email', value: 'a' },
    { type: 'submit', at: 1 },
  ];
  const event = queue[0]!;
  if (event.type === 'change') {
    const value: string = event.value;
    use(value);
  }

  // @ts-expect-error — value lives on the change variant only
  event.value;

  // @ts-expect-error — focus carries a field and nothing else
  reduce(EMPTY, { type: 'focus', field: 'email', value: 'a' });

  // @ts-expect-error — submit is stamped with `at`, not a field
  reduce(EMPTY, { type: 'submit', field: 'email' });

  // @ts-expect-error — 'reset' is not one of the four variants
  reduce(EMPTY, { type: 'reset' });

  // @ts-expect-error — assertNever accepts never, and a string is not never
  assertNever('reset');
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('every kind routes to its own handler', () => {
  eq(logLine({ kind: 'open', url: 'wss://api.test/s' }), 'open wss://api.test/s');
  eq(logLine({ kind: 'data', payload: 'hello', seq: 3 }), 'data #3 (5b)');
  eq(logLine({ kind: 'error', code: 1006, reason: 'lost' }), 'error 1006: lost');
  eq(logLine({ kind: 'close', clean: true }), 'closed cleanly');
});

test('the close handler reads its own boolean payload', () => {
  eq(logLine({ kind: 'close', clean: false }), 'closed abruptly');
});

test('match returns whatever the handlers return', () => {
  const weight: Handlers<number> = {
    open: () => 0,
    data: (msg) => msg.seq,
    error: (msg) => msg.code,
    close: (msg) => (msg.clean ? 1 : 0),
  };
  eq(match({ kind: 'data', payload: 'x', seq: 7 }, weight), 7);
  eq(match({ kind: 'error', code: 500, reason: 'x' }, weight), 500);
});

test('exactly one handler runs per message', () => {
  const open = spy(() => 'o');
  const data = spy(() => 'd');
  const counted: Handlers<string> = {
    open,
    data,
    error: () => 'e',
    close: () => 'c',
  };
  eq(match({ kind: 'data', payload: 'x', seq: 1 }, counted), 'd');
  eq(open.callCount, 0);
  eq(data.callCount, 1);
});

test('the handler receives the whole message object', () => {
  const seen: unknown[] = [];
  const spyMap: Handlers<void> = {
    open: (msg) => void seen.push(msg),
    data: (msg) => void seen.push(msg),
    error: (msg) => void seen.push(msg),
    close: (msg) => void seen.push(msg),
  };
  match({ kind: 'open', url: 'wss://x' }, spyMap);
  eq(seen, [{ kind: 'open', url: 'wss://x' }]);
  ok(seen.length === 1);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _t1 = Expect<Equal<MessageKind, 'open' | 'data' | 'error' | 'close'>>;
type _t2 = Expect<
  Equal<
    Parameters<Handlers<string>['data']>[0],
    { kind: 'data'; payload: string; seq: number }
  >
>;
type _t3 = Expect<Equal<keyof Handlers<string>, MessageKind>>;
type _t4 = Expect<Equal<ReturnType<typeof match<number>>, number>>;

function _typeTests() {
  const line: string = logLine({ kind: 'close', clean: true });
  use(line);

  const typed: Handlers<number> = {
    open: (msg) => msg.url.length,
    // @ts-expect-error — a data message carries no `code`
    data: (msg) => msg.code,
    error: (msg) => msg.code,
    close: (msg) => (msg.clean ? 1 : 0),
  };
  use(typed);

  // @ts-expect-error — every kind needs a handler, and close is missing
  const partial: Handlers<string> = { open: () => 'o', data: () => 'd', error: () => 'e' };
  use(partial);

  const extra: Handlers<string> = {
    open: () => 'o',
    data: () => 'd',
    error: () => 'e',
    close: () => 'c',
    // @ts-expect-error — 'ping' is not a message kind
    ping: () => 'p',
  };
  use(extra);

  // @ts-expect-error — the handler map is not optional
  match({ kind: 'close', clean: true });
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

const queued: JobIn<'queued'> = { state: 'queued', id: 'j1', queuedAt: 10 };

test('queued → running keeps the id and takes the new payload', () => {
  const running = advance(queued, 'running', { startedAt: 20, worker: 'w-3' });
  eq(running, { state: 'running', id: 'j1', startedAt: 20, worker: 'w-3' });
});

test('running → done carries the result', () => {
  const running = advance(queued, 'running', { startedAt: 20, worker: 'w-3' });
  const done = advance(running, 'done', { finishedAt: 30, result: '42' });
  eq(done.state, 'done');
  eq(done.result, '42');
});

test('running → failed, then failed → queued for a retry', () => {
  const running = advance(queued, 'running', { startedAt: 20, worker: 'w-3' });
  const failed = advance(running, 'failed', { error: 'boom', attempts: 1 });
  eq(failed.attempts, 1);
  const retried = advance(failed, 'queued', { queuedAt: 40 });
  eq(retried.state, 'queued');
});

test('an illegal pair that dodged the compiler throws at runtime', () => {
  const done = { state: 'done', id: 'j1', finishedAt: 1, result: 'x' } as Job;
  throws(
    () => advance(done as JobIn<'running'>, 'failed', { error: 'x', attempts: 1 }),
    'illegal transition'
  );
});

test('summarize reads the payload that belongs to each state', () => {
  eq(summarize(queued), 'j1 queued at 10');
  eq(summarize({ state: 'running', id: 'j2', startedAt: 1, worker: 'w-1' }),
    'j2 running on w-1');
  eq(summarize({ state: 'failed', id: 'j3', error: 'nope', attempts: 2 }),
    'j3 failed after 2: nope');
});

test('the runtime table tells the same story as Transitions', () => {
  eq(legalNext('queued'), ['running']);
  eq(legalNext('done'), []);
  ok(legalNext('running').includes('failed'));
});

// ──────────────────────────── type tests ─────────────────────────────────

type _t1 = Expect<Equal<JobState, 'queued' | 'running' | 'failed' | 'done'>>;
type _t2 = Expect<Equal<Transitions['running'], 'done' | 'failed'>>;
type _t3 = Expect<Equal<Transitions['done'], never>>;
type _t4 = Expect<
  Equal<
    JobIn<'failed'>,
    { state: 'failed'; id: string; error: string; attempts: number }
  >
>;

function _typeTests() {
  const running = advance(queued, 'running', { startedAt: 1, worker: 'w-1' });
  const pinned: JobIn<'running'> = running;
  const worker: string = running.worker;
  use(pinned, worker);

  // @ts-expect-error — running carries no result
  running.result;

  // @ts-expect-error — queued cannot jump straight to done
  advance(queued, 'done', { finishedAt: 2, result: 'x' });

  // @ts-expect-error — done is terminal: nothing may follow it
  advance(advance(running, 'done', { finishedAt: 2, result: 'x' }), 'queued', { queuedAt: 3 });

  // @ts-expect-error — entering failed needs attempts as well as error
  advance(running, 'failed', { error: 'boom' });

  // @ts-expect-error — 'paused' is not a state at all
  advance(queued, 'paused', { queuedAt: 1 });
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('a clean payload parses into a typed value', () => {
  const result = parseUser(FIXTURES.user);
  if (!result.ok) throw new Error('expected the ok branch');
  eq(result.value, {
    id: 'u_1',
    name: 'Ada',
    email: 'ada@lovelace.dev',
    active: true,
  });
});

test('isUser rejects the two broken user fixtures', () => {
  ok(!isUser(JSON.parse(FIXTURES.userNumericId)), 'numeric id must fail');
  ok(!isUser(JSON.parse(FIXTURES.userNoEmail)), 'missing email must fail');
});

test('isUser rejects things that are not plain objects', () => {
  ok(!isUser(JSON.parse(FIXTURES.notAnObject)));
  ok(!isUser(null));
  ok(!isUser('u_1'));
});

test('a clean order parses, items and all', () => {
  const result = parseOrder(FIXTURES.order);
  if (!result.ok) throw new Error('expected the ok branch');
  eq(result.value.items, [{ sku: 'a1', qty: 2 }]);
  eq(result.value.status, 'paid');
});

test('isOrder rejects a status outside the union and a half-built item', () => {
  ok(!isOrder(JSON.parse(FIXTURES.orderShoutyStatus)), 'PAID is not paid');
  ok(!isOrder(JSON.parse(FIXTURES.orderItemNoQty)), 'item needs a qty');
});

test('unparseable text comes back as data, never as an exception', () => {
  eq(parseOrder(FIXTURES.brokenJson), { ok: false, error: 'invalid json' });
  eq(parseUser(FIXTURES.userNoEmail), { ok: false, error: 'not a user' });
  eq(parseOrder(FIXTURES.orderShoutyStatus), {
    ok: false,
    error: 'not an order',
  });
});

// ──────────────────────────── type tests ─────────────────────────────────

type _t1 = Expect<
  Equal<Parsed<User>, { ok: true; value: User } | { ok: false; error: string }>
>;
type _t2 = Expect<Equal<ReturnType<typeof parseUser>, Parsed<User>>>;
type _t3 = Expect<Equal<ReturnType<typeof parseOrder>, Parsed<Order>>>;

function _typeTests() {
  const raw: unknown = JSON.parse(FIXTURES.user);

  // @ts-expect-error — raw is unknown until a guard has spoken
  raw.email;

  if (isUser(raw)) {
    const email: string = raw.email;
    use(email);

    // @ts-expect-error — User has no role field
    raw.role;
  }

  const result = parseUser(FIXTURES.user);

  // @ts-expect-error — value exists only on the ok branch
  result.value;

  if (result.ok) {
    const user: User = result.value;
    use(user);
  } else {
    const message: string = result.error;
    use(message);
  }

  const order = parseOrder(FIXTURES.order);
  if (order.ok) {
    // @ts-expect-error — status is a three-way literal union
    const status: 'paid' = order.value.status;
    use(status);
  }

  // @ts-expect-error — parse takes the raw text, not an already-parsed object
  parseUser({ id: 'u_1', name: 'Ada', email: 'a@b.c', active: true });
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('a real Error survives by identity, stack and all', () => {
  const original = new RangeError('too big');
  ok(toError(original) === original, 'expected the very same object');
});

test('a thrown string and a { message } object both lift to Error', () => {
  eq(toError('boom').message, 'boom');
  eq(toError({ message: 'from the api' }).message, 'from the api');
});

test('anything else is labelled rather than trusted', () => {
  eq(toError(404).message, 'unexpected throw: 404');
  eq(toError(null).message, 'unexpected throw: null');
  ok(toError(undefined) instanceof Error);
});

test('errorCode digs out string and numeric codes, and only those', () => {
  const enoent = Object.assign(new Error('missing'), { code: 'ENOENT' });
  eq(errorCode(enoent), 'ENOENT');
  eq(errorCode({ code: 429 }), '429');
  eq(errorCode({ code: { nested: true } }), null);
  eq(errorCode(new Error('plain')), null);
  eq(errorCode('ENOENT'), null);
});

test('safeRun turns both outcomes into data', () => {
  const good = safeRun(() => 6 * 7);
  if (!good.ok) throw new Error('expected the ok branch');
  eq(good.value, 42);

  const bad = safeRun((): number => {
    throw 'boom';
  });
  if (bad.ok) throw new Error('expected the failure branch');
  ok(bad.error instanceof Error, 'expected a real Error');
  eq(bad.error.message, 'boom');
});

test('safeRunAsync catches a rejection instead of leaking it', async () => {
  const good = await safeRunAsync(async () => 'ok');
  eq(good, { ok: true, value: 'ok' });

  const bad = await safeRunAsync(async (): Promise<string> => {
    throw Object.assign(new Error('gone'), { code: 410 });
  });
  if (bad.ok) throw new Error('expected the failure branch');
  eq(bad.error.message, 'gone');
  eq(errorCode(bad.error), '410');
});

// ──────────────────────────── type tests ─────────────────────────────────

type _t1 = Expect<
  Equal<
    Attempt<number>,
    { ok: true; value: number } | { ok: false; error: Error }
  >
>;
type _t2 = Expect<Equal<ReturnType<typeof toError>, Error>>;
type _t3 = Expect<Equal<ReturnType<typeof errorCode>, string | null>>;
type _t4 = Expect<Equal<ReturnType<typeof safeRun<string>>, Attempt<string>>>;

function _typeTests() {
  const caught: unknown = new Error('x');

  // @ts-expect-error — a caught value is unknown, so nothing is readable
  caught.message;

  // @ts-expect-error — including the code you are about to go looking for
  caught.code;

  const message: string = toError(caught).message;
  use(message);

  // @ts-expect-error — normalising gives you an Error, not your subclass
  toError(caught).status;

  const code = errorCode(caught);
  // @ts-expect-error — errorCode may return null, so it is not a string
  const asString: string = code;
  use(asString);

  const result = safeRun(() => 42);

  // @ts-expect-error — value exists only after you have checked ok
  result.value;

  if (result.ok) {
    const value: number = result.value;
    use(value);
  } else {
    const failure: Error = result.error;
    use(failure);
  }

  const pending: Promise<Attempt<string>> = safeRunAsync(async () => 'x');
  use(pending);

  // @ts-expect-error — errorCode needs something to inspect
  errorCode();
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('sortBy orders on a numeric key', () => {
  eq(sortBy(TICKETS, 'priority').map((t: Ticket) => t.id), ['t1', 't3', 't2']);
});

test('sortBy orders on a string key and leaves the input alone', () => {
  eq(sortBy(TICKETS, 'title').map((t: Ticket) => t.id), ['t1', 't3', 't2']);
  eq(TICKETS.map((t) => t.id), ['t3', 't1', 't2']);
});

test('whereEq filters on the value at that key', () => {
  eq(whereEq(TICKETS, 'assignee', 'ada').map((t: Ticket) => t.id), ['t3', 't2']);
  eq(whereEq(TICKETS, 'open', false).map((t: Ticket) => t.id), ['t2']);
  eq(whereEq(TICKETS, 'priority', 9), []);
});

test('project keeps exactly the keys it was given', () => {
  eq(project(TICKETS[0]!, ['id', 'title']), {
    id: 't3',
    title: 'Slow query',
  });
});

test('project with no keys is an empty object, not a copy', () => {
  const empty = project(TICKETS[0]!, []);
  eq(Object.keys(empty), []);
  ok(empty !== TICKETS[0]);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _t1 = Expect<Equal<ReturnType<typeof sortBy<Ticket, 'priority'>>, Ticket[]>>;
type _t2 = Expect<Equal<Parameters<typeof whereEq<Ticket, 'priority'>>[2], number>>;
type _t3 = Expect<
  Equal<
    ReturnType<typeof project<Ticket, 'id' | 'title'>>,
    Pick<Ticket, 'id' | 'title'>
  >
>;

function _typeTests() {
  const ticket = TICKETS[0]!;

  const byPriority: Ticket[] = sortBy(TICKETS, 'priority');
  use(byPriority);

  // @ts-expect-error — 'nope' is not a key of Ticket
  sortBy(TICKETS, 'nope');

  const open: Ticket[] = whereEq(TICKETS, 'open', true);
  use(open);

  // @ts-expect-error — priority is a number, so 'high' cannot match it
  whereEq(TICKETS, 'priority', 'high');

  // @ts-expect-error — and neither can a boolean
  whereEq(TICKETS, 'assignee', true);

  const slim = project(ticket, ['id', 'title']);
  const title: string = slim.title;
  use(title);

  // @ts-expect-error — priority was not projected, so it is not there
  slim.priority;

  // @ts-expect-error — every key must be a key of Ticket
  project(ticket, ['id', 'nope']);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('setField changes one field and copies the rest', () => {
  const next = setField(ADA, 'age', 37);
  eq(next, { ...ADA, age: 37 });
});

test('setField never mutates the form it was given', () => {
  setField(ADA, 'theme', 'dark');
  eq(ADA.theme, 'light');
});

test('diff reports only what actually changed', () => {
  const next = setField(setField(ADA, 'age', 37), 'theme', 'dark');
  eq(diff(ADA, next), { age: 37, theme: 'dark' });
});

test('diff of two equal forms is empty, not full of undefined', () => {
  const patch = diff(ADA, { ...ADA });
  eq(Object.keys(patch), []);
  ok(!('age' in patch));
});

test('applyPatch puts a diff back where it came from', () => {
  const next = setField(setField(ADA, 'newsletter', true), 'email', 'a@b.c');
  eq(applyPatch(ADA, diff(ADA, next)), next);
});

test('an empty patch is an identity', () => {
  eq(applyPatch(ADA, {}), ADA);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _t1 = Expect<Equal<ReturnType<typeof diff<Profile>>, Partial<Profile>>>;
type _t2 = Expect<
  Equal<Parameters<typeof setField<Profile, 'theme'>>[2], 'light' | 'dark'>
>;
type _t3 = Expect<Equal<ReturnType<typeof setField<Profile, 'age'>>, Profile>>;
type _t4 = Expect<Equal<Parameters<typeof applyPatch<Profile>>[1], Partial<Profile>>>;

function _typeTests() {
  const dark = setField(ADA, 'theme', 'dark');
  const theme: 'light' | 'dark' = dark.theme;
  use(theme);

  // @ts-expect-error — age is a number, not a numeric string
  setField(ADA, 'age', '37');

  // @ts-expect-error — nickname is not a field of Profile
  setField(ADA, 'nickname', 'Addy');

  // @ts-expect-error — theme is a two-way literal union
  setField(ADA, 'theme', 'blue');

  const patch = diff(ADA, dark);
  const maybeAge: number | undefined = patch.age;
  use(maybeAge);

  // @ts-expect-error — Partial means every field may be missing
  const definitelyAge: number = patch.age;
  use(definitelyAge);

  // @ts-expect-error — a patch may only carry fields of the same shape
  applyPatch(ADA, { nickname: 'Addy' });

  // @ts-expect-error — and they must still hold the right types
  applyPatch(ADA, { age: '37' });
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('the public profile is three fields and no secrets', () => {
  eq(toPublicProfile(ADA), { id: 'e1', firstName: 'Ada', lastName: 'Lovelace' });
});

test('the admin row keeps everything except the ssn', () => {
  const row = toAdminRow(ADA) as Record<string, unknown>;
  ok(!('ssn' in row), 'the ssn must not survive');
  eq(row.salaryCents, 1_200_00);
  eq(Object.keys(row).length, 7);
});

test('the directory is keyed by id', () => {
  const directory = toDirectory([ADA, BO]);
  eq(Object.keys(directory), ['e1', 'e2']);
  eq(directory.e2, { id: 'e2', firstName: 'Bo', lastName: 'Diddley' });
