type _v3 = Expect<Equal<UpdatePayload, Partial<Omit<Employee, 'id' | 'ssn'>>>>;
type _v4 = Expect<Equal<AdminRow, Readonly<Omit<Employee, 'ssn'>>>>;
type _v5 = Expect<Equal<Directory, Record<string, PublicProfile>>>;
