const LEVELS = { debug: 10, info: 20, warn: 30 };

export function levelValue(name: keyof typeof LEVELS): number {
  return LEVELS[name];
}

// ── 5 ────────────────────────────────────────────────────────────────────

export function messageOf(fn: () => void): string {
  try {
    fn();
    return 'ok';
  } catch (e) {
    return e instanceof Error ? e.message : String(e);
  }
}

