type _t2 = Expect<Equal<Parameters<typeof priceLabel>[0], string>>;
type _t3 = Expect<Equal<ReturnType<typeof widthOf>, number>>;
type _t4 = Expect<
  Equal<Parameters<typeof levelValue>[0], 'debug' | 'info' | 'warn'>
